/**
 * Rough.js v4.6-compatible Canvas Engine (Bundled offline for ExcaliCursor)
 * Implements seeded hand-drawn double-line, cubic bezier curve, hachure fill,
 * rectangle, polygon (diamond), ellipse, line, linearPath, and curve rendering.
 */
(function (global) {
  "use strict";

  class Random {
    constructor(seed) {
      this.seed = seed || Math.floor(Math.random() * 2147483647) || 1;
    }
    next() {
      this.seed = (Math.imul(48271, this.seed) & 2147483647);
      return (this.seed & 2147483647) / 2147483648;
    }
  }

  const defaultOptions = {
    maxRandomnessOffset: 2,
    roughness: 1.2,
    bowing: 1,
    stroke: "#1e1e1e",
    strokeWidth: 3,
    curveTightness: 0,
    curveFitting: 0.95,
    curveStepCount: 9,
    fillStyle: "hachure",
    fillWeight: -1,
    hachureAngle: -41,
    hachureGap: -1,
    disableMultiStroke: false,
    seed: 0
  };

  function cloneOptions(options) {
    const out = Object.assign({}, defaultOptions, options || {});
    out.randomizer = new Random(out.seed || Math.floor(Math.random() * 1e9));
    return out;
  }

  function randOffset(x, o, ops = 1) {
    return o.roughness * ops * (o.randomizer.next() * 2 - 1);
  }

  function randOffsetWithRange(min, max, o, ops = 1) {
    return o.roughness * ops * (o.randomizer.next() * (max - min) + min);
  }

  function doubleLineOps(x1, y1, x2, y2, o, filling = false) {
    const singleStroke = filling ? o.disableMultiStrokeFill : o.disableMultiStroke;
    const o1 = lineOps(x1, y1, x2, y2, o, true, false);
    if (singleStroke) {
      return o1;
    }
    const o2 = lineOps(x1, y1, x2, y2, o, true, true);
    return o1.concat(o2);
  }

  function lineOps(x1, y1, x2, y2, o, move, overlay) {
    const lengthSq = Math.pow(x1 - x2, 2) + Math.pow(y1 - y2, 2);
    const length = Math.sqrt(lengthSq);
    let roughnessGain = 1;
    if (length < 200) {
      roughnessGain = 1;
    } else if (length > 500) {
      roughnessGain = 0.4;
    } else {
      roughnessGain = -0.0016668 * length + 1.233334;
    }

    let offset = o.maxRandomnessOffset || 0;
    if (offset * offset * 100 > lengthSq) {
      offset = length / 10;
    }
    const halfOffset = offset / 2;
    const divergePoint = 0.2 + o.randomizer.next() * 0.2;

    let midDispX = (o.bowing * o.maxRandomnessOffset * (y2 - y1)) / 200;
    let midDispY = (o.bowing * o.maxRandomnessOffset * (x1 - x2)) / 200;
    midDispX = randOffset(midDispX, o, roughnessGain);
    midDispY = randOffset(midDispY, o, roughnessGain);

    const ops = [];
    const randomHalf = () => randOffset(halfOffset, o, roughnessGain);
    const randomFull = () => randOffset(offset, o, roughnessGain);

    if (move) {
      if (overlay) {
        ops.push({
          op: "move",
          data: [x1 + randomHalf(), y1 + randomHalf()]
        });
      } else {
        ops.push({
          op: "move",
          data: [x1 + randomFull(), y1 + randomFull()]
        });
      }
    }

    if (overlay) {
      ops.push({
        op: "bcurveTo",
        data: [
          midDispX + x1 + (x2 - x1) * divergePoint + randomHalf(),
          midDispY + y1 + (y2 - y1) * divergePoint + randomHalf(),
          midDispX + x1 + 2 * (x2 - x1) * divergePoint + randomHalf(),
          midDispY + y1 + 2 * (y2 - y1) * divergePoint + randomHalf(),
          x2 + randomHalf(),
          y2 + randomHalf()
        ]
      });
    } else {
      ops.push({
        op: "bcurveTo",
        data: [
          midDispX + x1 + (x2 - x1) * divergePoint + randomFull(),
          midDispY + y1 + (y2 - y1) * divergePoint + randomFull(),
          midDispX + x1 + 2 * (x2 - x1) * divergePoint + randomFull(),
          midDispY + y1 + 2 * (y2 - y1) * divergePoint + randomFull(),
          x2 + randomFull(),
          y2 + randomFull()
        ]
      });
    }
    return ops;
  }

  function curveWithOffset(points, offset, o) {
    const ps = [];
    ps.push([
      points[0][0] + randOffset(offset, o),
      points[0][1] + randOffset(offset, o)
    ]);
    ps.push([
      points[0][0] + randOffset(offset, o),
      points[0][1] + randOffset(offset, o)
    ]);
    for (let i = 1; i < points.length; i++) {
      ps.push([
        points[i][0] + randOffset(offset, o),
        points[i][1] + randOffset(offset, o)
      ]);
      if (i === points.length - 1) {
        ps.push([
          points[i][0] + randOffset(offset, o),
          points[i][1] + randOffset(offset, o)
        ]);
      }
    }
    return curveOps(ps, null, o);
  }

  function curveOps(points, closePoint, o) {
    const len = points.length;
    const ops = [];
    if (len > 3) {
      const s = 1 - o.curveTightness;
      ops.push({ op: "move", data: [points[1][0], points[1][1]] });
      for (let i = 1; i + 2 < len; i++) {
        const b0 = points[i];
        const b1 = [
          b0[0] + (s * points[i + 1][0] - s * points[i - 1][0]) / 6,
          b0[1] + (s * points[i + 1][1] - s * points[i - 1][1]) / 6
        ];
        const b2 = [
          points[i + 1][0] + (s * points[i][0] - s * points[i + 2][0]) / 6,
          points[i + 1][1] + (s * points[i][1] - s * points[i + 2][1]) / 6
        ];
        const b3 = [points[i + 1][0], points[i + 1][1]];
        ops.push({
          op: "bcurveTo",
          data: [b1[0], b1[1], b2[0], b2[1], b3[0], b3[1]]
        });
      }
      if (closePoint && closePoint.length === 2) {
        const ro = o.maxRandomnessOffset;
        ops.push({
          op: "lineTo",
          data: [
            closePoint[0] + randOffset(ro, o),
            closePoint[1] + randOffset(ro, o)
          ]
        });
      }
    } else if (len === 3) {
      ops.push({ op: "move", data: [points[1][0], points[1][1]] });
      ops.push({
        op: "bcurveTo",
        data: [
          points[1][0],
          points[1][1],
          points[2][0],
          points[2][1],
          points[2][0],
          points[2][1]
        ]
      });
    } else if (len === 2) {
      ops.push(...doubleLineOps(points[0][0], points[0][1], points[1][0], points[1][1], o));
    }
    return ops;
  }

  function computeEllipsePoints(increment, cx, cy, rx, ry, offset, overlap, o) {
    const corePoints = [];
    const allPoints = [];
    const radOffset = randOffset(0.5, o) - Math.PI / 2;

    allPoints.push([
      randOffset(offset, o) + cx + 0.9 * rx * Math.cos(radOffset - increment),
      randOffset(offset, o) + cy + 0.9 * ry * Math.sin(radOffset - increment)
    ]);

    const endAngle = Math.PI * 2 + radOffset - 0.01;
    for (let angle = radOffset; angle < endAngle; angle += increment) {
      const p = [
        randOffset(offset, o) + cx + rx * Math.cos(angle),
        randOffset(offset, o) + cy + ry * Math.sin(angle)
      ];
      corePoints.push(p);
      allPoints.push(p);
    }

    allPoints.push([
      randOffset(offset, o) + cx + rx * Math.cos(radOffset + Math.PI * 2 + overlap * 0.5),
      randOffset(offset, o) + cy + ry * Math.sin(radOffset + Math.PI * 2 + overlap * 0.5)
    ]);
    allPoints.push([
      randOffset(offset, o) + cx + 0.98 * rx * Math.cos(radOffset + overlap),
      randOffset(offset, o) + cy + 0.98 * ry * Math.sin(radOffset + overlap)
    ]);
    allPoints.push([
      randOffset(offset, o) + cx + 0.9 * rx * Math.cos(radOffset + overlap * 0.5),
      randOffset(offset, o) + cy + 0.9 * ry * Math.sin(radOffset + overlap * 0.5)
    ]);

    return [allPoints, corePoints];
  }

  function polygonHachureOps(points, o) {
    if (!points || points.length < 3) return [];
    let gap = o.hachureGap > 0 ? o.hachureGap : o.strokeWidth * 4;
    gap = Math.max(gap, 5);

    const angleRad = ((o.hachureAngle || -41) * Math.PI) / 180;
    const cos = Math.cos(angleRad);
    const sin = Math.sin(angleRad);

    // Rotate polygon so scanlines are horizontal
    const rotated = points.map(([x, y]) => [
      x * cos - y * sin,
      x * sin + y * cos
    ]);

    let minY = Infinity;
    let maxY = -Infinity;
    for (const [, ry] of rotated) {
      if (ry < minY) minY = ry;
      if (ry > maxY) maxY = ry;
    }

    const ops = [];
    for (let y = minY + gap; y < maxY; y += gap) {
      const intersections = [];
      for (let i = 0; i < rotated.length; i++) {
        const p1 = rotated[i];
        const p2 = rotated[(i + 1) % rotated.length];
        if ((p1[1] <= y && p2[1] > y) || (p2[1] <= y && p1[1] > y)) {
          const t = (y - p1[1]) / (p2[1] - p1[1]);
          intersections.push(p1[0] + t * (p2[0] - p1[0]));
        }
      }
      intersections.sort((a, b) => a - b);
      for (let i = 0; i + 1 < intersections.length; i += 2) {
        const rx1 = intersections[i];
        const rx2 = intersections[i + 1];
        // Rotate back
        const x1 = rx1 * cos + y * sin;
        const y1 = -rx1 * sin + y * cos;
        const x2 = rx2 * cos + y * sin;
        const y2 = -rx2 * sin + y * cos;
        ops.push(...lineOps(x1, y1, x2, y2, o, true, false));
      }
    }
    return ops;
  }

  function hachureEllipseOps(cx, cy, rx, ry, o) {
    if (rx <= 0 || ry <= 0) return [];
    let gap = o.hachureGap > 0 ? o.hachureGap : o.strokeWidth * 4;
    gap = Math.max(gap, 5);
    const ops = [];
    const angle = ((o.hachureAngle || -41) * Math.PI) / 180;
    const cos = Math.cos(angle);
    const sin = Math.sin(angle);
    const maxR = Math.max(rx, ry);

    for (let offset = -maxR + gap; offset < maxR; offset += gap) {
      const norm = offset / maxR;
      if (Math.abs(norm) >= 1) continue;
      const halfChord = Math.sqrt(1 - norm * norm);
      const px1 = -halfChord * rx;
      const py1 = norm * ry;
      const px2 = halfChord * rx;
      const py2 = norm * ry;

      const x1 = cx + px1 * cos - py1 * sin;
      const y1 = cy + px1 * sin + py1 * cos;
      const x2 = cx + px2 * cos - py2 * sin;
      const y2 = cy + px2 * sin + py2 * cos;
      ops.push(...lineOps(x1, y1, x2, y2, o, true, false));
    }
    return ops;
  }

  class RoughCanvas {
    constructor(canvas, config) {
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.defaultOptions = Object.assign({}, defaultOptions, (config && config.options) || {});
    }

    _drawSet(ctx, opSet, o) {
      ctx.save();
      ctx.lineCap = "round";
      ctx.lineJoin = "round";

      if (opSet.type === "path") {
        ctx.strokeStyle = o.stroke === "none" ? "transparent" : o.stroke;
        ctx.lineWidth = o.strokeWidth;
        this._execOps(ctx, opSet.ops);
        ctx.stroke();
      } else if (opSet.type === "fillSketch") {
        let fweight = o.fillWeight;
        if (fweight < 0) {
          fweight = o.strokeWidth / 2;
        }
        ctx.strokeStyle = o.fill || o.stroke;
        ctx.lineWidth = fweight;
        this._execOps(ctx, opSet.ops);
        ctx.stroke();
      } else if (opSet.type === "fillPath") {
        ctx.fillStyle = o.fill || "transparent";
        this._execOps(ctx, opSet.ops);
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }

    _execOps(ctx, ops) {
      ctx.beginPath();
      for (const item of ops) {
        const d = item.data;
        if (item.op === "move") {
          ctx.moveTo(d[0], d[1]);
        } else if (item.op === "bcurveTo") {
          ctx.bezierCurveTo(d[0], d[1], d[2], d[3], d[4], d[5]);
        } else if (item.op === "lineTo") {
          ctx.lineTo(d[0], d[1]);
        }
      }
    }

    line(x1, y1, x2, y2, options) {
      const o = cloneOptions(options);
      const ops = doubleLineOps(x1, y1, x2, y2, o);
      this._drawSet(this.ctx, { type: "path", ops }, o);
    }

    polygon(points, options) {
      const o = cloneOptions(options);
      if (!points || points.length < 2) return;

      if (o.fill && o.fill !== "transparent" && o.fill !== "none") {
        if (o.fillStyle === "solid") {
          const fillOps = points.map((pt, idx) => ({
            op: idx === 0 ? "move" : "lineTo",
            data: [pt[0], pt[1]]
          }));
          this._drawSet(this.ctx, { type: "fillPath", ops: fillOps }, o);
        } else {
          const fillOps = polygonHachureOps(points, o);
          this._drawSet(this.ctx, { type: "fillSketch", ops: fillOps }, o);
        }
      }

      const ops = [];
      for (let i = 0; i < points.length; i++) {
        const p1 = points[i];
        const p2 = points[(i + 1) % points.length];
        ops.push(...doubleLineOps(p1[0], p1[1], p2[0], p2[1], o));
      }
      this._drawSet(this.ctx, { type: "path", ops }, o);
    }

    rectangle(x, y, width, height, options) {
      const points = [
        [x, y],
        [x + width, y],
        [x + width, y + height],
        [x, y + height]
      ];
      this.polygon(points, options);
    }

    ellipse(x, y, width, height, options) {
      const o = cloneOptions(options);
      const rx = Math.abs(width / 2);
      const ry = Math.abs(height / 2);
      if (rx < 0.5 && ry < 0.5) return;

      const perimeter = Math.PI * 2 * Math.sqrt((rx * rx + ry * ry) / 2);
      const stepCount = Math.max(
        o.curveStepCount,
        (o.curveStepCount / Math.sqrt(200)) * Math.sqrt(perimeter)
      );
      const increment = (Math.PI * 2) / stepCount;
      const curveFitRandomness = 1 - o.curveFitting;
      const rxAdj = rx + randOffset(rx * curveFitRandomness, o);
      const ryAdj = ry + randOffset(ry * curveFitRandomness, o);

      if (o.fill && o.fill !== "transparent" && o.fill !== "none") {
        if (o.fillStyle === "solid") {
          const [, corePts] = computeEllipsePoints(increment, x, y, rxAdj, ryAdj, 0, 0, o);
          const fillOps = curveOps(corePts, null, o);
          this._drawSet(this.ctx, { type: "fillPath", ops: fillOps }, o);
        } else {
          const fillOps = hachureEllipseOps(x, y, rxAdj, ryAdj, o);
          this._drawSet(this.ctx, { type: "fillSketch", ops: fillOps }, o);
        }
      }

      const overlap1 = increment * randOffsetWithRange(0.1, randOffsetWithRange(0.4, 1, o), o);
      const [ap1] = computeEllipsePoints(increment, x, y, rxAdj, ryAdj, 1, overlap1, o);
      let ops = curveOps(ap1, null, o);

      if (!o.disableMultiStroke) {
        const [ap2] = computeEllipsePoints(increment, x, y, rxAdj, ryAdj, 1.5, 0, o);
        ops = ops.concat(curveOps(ap2, null, o));
      }

      this._drawSet(this.ctx, { type: "path", ops }, o);
    }

    linearPath(points, options) {
      const o = cloneOptions(options);
      if (!points || points.length < 2) return;
      const ops = [];
      for (let i = 0; i < points.length - 1; i++) {
        ops.push(...doubleLineOps(points[i][0], points[i][1], points[i + 1][0], points[i + 1][1], o));
      }
      this._drawSet(this.ctx, { type: "path", ops }, o);
    }

    curve(points, options) {
      const o = cloneOptions(options);
      if (!points || points.length < 2) return;
      const o1 = curveWithOffset(points, 1 * (1 + o.roughness * 0.2), o);
      let ops = o1;
      if (!o.disableMultiStroke) {
        const o2 = curveWithOffset(points, 1.5 * (1 + o.roughness * 0.22), o);
        ops = o1.concat(o2);
      }
      this._drawSet(this.ctx, { type: "path", ops }, o);
    }
  }

  global.rough = {
    canvas: function (canvas, config) {
      return new RoughCanvas(canvas, config);
    }
  };
})(window);
